if (numberOfChecks <= 0) return false;

const double epsilon = 1e-10;
std::mt19937 rng(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);

int insideCount = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    double dx = dist(rng);
    double dy = dist(rng);
    double dz = dist(rng);
    double len = std::sqrt(dx*dx + dy*dy + dz*dz);
    if (len < epsilon) {
        --i;
        continue;
    }
    dx /= len; dy /= len; dz /= len;

    CGALPoint origin(p.x(), p.y(), p.z());
    CGALPoint dir(dx, dy, dz);
    CGALRay ray(origin, dir);

    std::list<CGALTriangle> intersections;
    tree.ray_intersection(ray, std::back_inserter(intersections));

    int crossings = 0;
    for (const auto& tri : intersections) {
        CGALPoint intersection;
        if (CGAL::do_intersect(ray, tri)) {
            auto result = CGAL::intersection(ray, tri);
            if (result) {
                if (const CGALPoint* point = boost::get<CGALPoint>(&*result)) {
                    if (CGAL::squared_distance(*point, origin) > epsilon) {
                        crossings++;
                    }
                }
            }
        }
    }
    if (crossings % 2 == 1) {
        insideCount++;
    }
}

return insideCount > numberOfChecks / 2;

